// Six AI results the OpenAI-release triage ran into that are not part of the
// release, reviewed on 7 October 2026. Data in separate-ai-results-2026-10-07.json.
//
// Published (3):
//   * graham-spherical-ramsey-conjecture: Palvolgyi, arXiv:2609.23327, a
//     seven-point circle set that is not Ramsey; ChatGPT wrote the manuscript
//     and the author disclaims the proofs and ideas. Candidate, unreviewed.
//   * critical-site-percolation-z-d: Bou-Rabee and Leder, no percolation at
//     criticality for site percolation on Z^d, d >= 3, "generated by ChatGPT
//     5.6, prompted by Ahmed Bou-Rabee", with a Lean development whose
//     comparator challenge states the headline. Candidate, lean-checked.
//   * block-sensitivity-spectral-sensitivity-squared: Meiburg,
//     arXiv:2608.00851, answers the Aaronson-Ben-David-Kothari-Rao-Tal
//     question bs(f) = O(lambda(f)^2) negatively; GPT-5.6-Sol suggested key
//     ideas. Candidate, lean-checked.
//
// Not published:
//   * Chen, arXiv:2609.24142 (small Cohen-Macaulay counterexample): the AI
//     role is a research and writing aid with no proofs or ideas credited to
//     the model, too thin for scope. Linked with a priority note from the
//     release entry, whose description of his hypothesis is corrected.
//   * Truffet (mean-payoff games): no AI involvement disclosed. Linked from
//     the release entry, whose "Priority note" is relabelled "Conflicting
//     claim", since his is a stronger claim the release rebuts.
//   * Carenini, ECCC TR26-229 (k-SAT threshold): states that no argument was
//     generated by a language model. One sentence on the release entry.
//
// Dry run by default. --lint checks with no database. --apply writes.

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { guardedPrisma } from "./lib/guarded-prisma";
import { checkStoredEntry } from "../src/lib/field-validation";
import { CURATOR_FIELDS, EDITABLE_FIELDS } from "../src/lib/editable";
import { charLength, canonical } from "../src/lib/char-length";

const APPLY = process.argv.includes("--apply");
const LINT = process.argv.includes("--lint");
const ADMIN_EMAIL = "rasmus.lindahl1996@gmail.com";
const SPECS = [...EDITABLE_FIELDS, ...CURATOR_FIELDS];
const LIMIT = new Map<string, number>();
for (const s of SPECS) if (s.maxLength) LIMIT.set(s.key, s.maxLength);
const FIELD_LABEL: Record<string, string> = {
  resultNote: "What was actually shown",
  verificationNote: "Verification note",
};

type Link = { label: string; url: string; kind: string };
interface Entry {
  slug: string;
  fields: Record<string, unknown>;
  links: Link[];
}
interface Action {
  slug: string;
  link?: Link;
  field?: "resultNote" | "verificationNote";
  append?: string;
  replace?: [string, string];
}

const DATA = JSON.parse(readFileSync(join(__dirname, "separate-ai-results-2026-10-07.json"), "utf8")) as {
  entries: Entry[];
  actions: Action[];
};

function lint(): number {
  let bad = 0;
  for (const e of DATA.entries) {
    console.log(e.slug);
    for (const [k, v] of Object.entries(e.fields)) {
      if (typeof v !== "string") continue;
      const c = charLength(canonical(v));
      const lim = LIMIT.get(k);
      if (lim && c > lim) {
        console.log(`  ${k}: ${c}/${lim} OVER`);
        bad++;
      }
      if (/—/.test(v)) {
        console.log(`  ${k}: EM DASH`);
        bad++;
      }
    }
    for (const x of checkStoredEntry({ specs: SPECS, fields: e.fields, links: e.links, sourceUrl: e.fields.sourceUrl as string })) {
      console.log(`  RULE: ${x.field}: ${x.problem}`);
      bad++;
    }
  }
  for (const a of DATA.actions) {
    for (const s of [a.append, a.link?.label, ...(a.replace ?? [])]) {
      if (s && /—/.test(s)) {
        console.log(`${a.slug}: EM DASH in action`);
        bad++;
      }
    }
    if (a.link && a.link.label.length > 120) {
      console.log(`${a.slug}: link label over 120`);
      bad++;
    }
  }
  return bad;
}

async function main() {
  const bad = lint();
  if (LINT) {
    console.log(bad ? `\n${bad} local violation(s)` : "\nlocal checks ok");
    process.exitCode = bad ? 1 : 0;
    return;
  }
  if (bad) throw new Error(`${bad} local violation(s) - nothing written`);

  const prisma = guardedPrisma();
  try {
    const [{ db }] = await prisma.$queryRawUnsafe<{ db: string }[]>("SELECT current_database() AS db");
    console.log(`\ndatabase: ${db}${db === "vibemathed" ? "  (PRODUCTION)" : ""}\n`);
    const admin = await prisma.user.findUnique({ where: { email: ADMIN_EMAIL } });
    if (!admin) throw new Error("no admin");

    for (const e of DATA.entries) {
      const existing = await prisma.problem.findUnique({ where: { slug: e.slug }, select: { status: true } });
      const f = e.fields;
      console.log(`${existing ? "SKIP  " : "CREATE"} ${e.slug}  [${f.resolution}, ${f.verification}, sig ${f.significance}]  ${e.links.length} links`);
      if (existing || !APPLY) continue;
      await prisma.$transaction([
        prisma.problem.create({
          data: {
            slug: e.slug,
            ...(f as object),
            status: "published",
            links: { create: e.links.map((l, position) => ({ ...l, position })) },
          } as never,
        }),
        prisma.problemActivity.create({
          data: {
            problem: { connect: { slug: e.slug } },
            user: { connect: { id: admin.id } },
            userName: admin.pseudonym ?? null,
            type: "created",
          },
        }),
      ]);
      console.log("  created");
    }

    // Pre-flight every action before writing any of them.
    for (const a of DATA.actions) {
      const t = await prisma.problem.findUnique({
        where: { slug: a.slug },
        select: { id: true, resultNote: true, verificationNote: true, links: { select: { url: true } } },
      });
      if (!t) throw new Error(`${a.slug} not found`);
      if (a.link) {
        const has = t.links.some((l) => l.url === a.link!.url);
        console.log(`LINK    ${a.slug}: ${has ? "present" : `add ${a.link.url}`}`);
        if (APPLY && !has) {
          await prisma.problemLink.create({ data: { ...a.link, position: t.links.length, problemId: t.id } });
        }
      }
      if (a.field && (a.append || a.replace)) {
        const old = t[a.field] ?? "";
        let next = old;
        if (a.append && !old.includes(a.append)) next = `${old}${old ? " " : ""}${a.append}`;
        if (a.replace) {
          if (old.includes(a.replace[0])) next = next.replace(a.replace[0], a.replace[1]);
          else if (!old.includes(a.replace[1])) throw new Error(`${a.slug}: text to replace not found`);
        }
        next = canonical(next);
        const n = charLength(next);
        const lim = LIMIT.get(a.field)!;
        if (n > lim) throw new Error(`${a.slug} ${a.field}: ${n}/${lim} over`);
        console.log(`${a.replace ? "REPLACE" : "APPEND "} ${a.slug} ${a.field}: ${next === old ? "already done" : `${charLength(old)} -> ${n}/${lim}`}`);
        if (APPLY && next !== old) {
          await prisma.$transaction([
            prisma.problem.update({ where: { id: t.id }, data: { [a.field]: next } }),
            prisma.problemActivity.create({
              data: {
                problemId: t.id,
                userId: admin.id,
                userName: admin.pseudonym ?? null,
                type: "updated",
                field: FIELD_LABEL[a.field],
                oldValue: old,
                newValue: next,
              },
            }),
          ]);
        }
      }
    }

    console.log(APPLY ? "\nAPPLIED" : "\nDRY RUN - pass --apply to write");
  } finally {
    await prisma.$disconnect();
  }
}

main();
